from pathlib import Path
import sys
p=Path(sys.argv[1]) if len(sys.argv)>1 else Path('project/app/src/main/assets/index.html')
s=p.read_text(encoding='utf-8')
start=s.find('function renderRaidRun(){')
end=s.find('\n  const startRaid=',start)
if start<0 or end<0: raise SystemExit('renderRaidRun block not found')
new=r'''function renderRaidRun(){
  const p=hero(),a=p._v20Raid;if(!a)return renderRaidHub();const ev=a.event,e=a.enemy,pl=a.plan||raidV32Plan(a.cave);
  const stageName=['Вход','Следы','Ловушка','Дверь кургана','Подземный грот','Глубины','Алтарь','Чёрный коридор','Преддверие','Босс'][a.stage-1];
  const map=`<div class="v34-mapline">${Array.from({length:10},(_,i)=>`<span class="${i<a.stage-1?'done':''} ${i===a.stage-1?'now':''}">${i===9?'👑':i+1}</span>`).join('')}</div>`;
  const injured=a.injuries?.length?`<div class="v34-injury">🩸 <b>Ранения:</b> ${a.injuries.map(x=>esc2(x)).join(' • ')}</div>`:'';
  const mastery=raidV32EnsureMastery();
  const danger=caves.find(c=>c.id===a.cave)?.danger||3;
  const summary=`<details class="v38-raid-details"><summary><span>🗡️ Эффекты</span><span>🩸 Опасность ${danger}/10</span><span>🎒 Добыча ${a.loot?.length||0}</span><b>⌄</b></summary><div class="v38-raid-details-body"><div class="v34-chip"><b>${pl.modifier.icon} ${esc2(pl.modifier.name)}</b>${esc2(pl.modifier.desc)}</div><div class="v34-chip"><b>${pl.relic.icon} ${esc2(pl.relic.name)}</b>${esc2(pl.relic.desc)}</div><div class="v34-chip"><b>${pl.contract.icon} ${esc2(pl.contract.name)}</b>${esc2(pl.contract.desc)}</div><div class="v34-chip"><b>🔥 Серия ${mastery.streak||0}</b>Элиты ${a.elites||0} • секреты ${a.secrets||0}</div></div></details>${a.route?`<div class="v32-route"><b>${a.route==='secret'?'🔐 Тайный маршрут':a.route==='risk'?'⚔️ Опасный маршрут':'🛡️ Безопасный маршрут'}</b> — следующий бой изменён.</div>`:''}${injured}`;
  let body='';
  if(ev){body=`<div class="v20-event v38-event"><div class="v20-event-title"><span>${ev.icon}</span><div><small>СЛУЧАЙНОЕ СОБЫТИЕ ${a.stage}/10</small><h2>${esc2(ev.title)}</h2><p>${esc2(ev.text)}</p></div></div><div class="v20-choices">${ev.c.map(x=>`<button class="v20-choice" data-v20-action="event" data-id="${x[0]}"><b>${esc2(x[1])}</b><small>${esc2(x[2])}</small></button>`).join('')}</div></div>`}
  else{
    if(!e){spawnEnemy(a);return renderRaidRun()}
    const pct=Math.max(0,Math.round(e.hp/e.max*100)),hpPct=Math.max(0,Math.round(a.hp/(a.maxHp||hpMax())*100));
    const playerAttack=typeof window.heroAttack==='function'?Math.round(window.heroAttack()):12;const playerArmor=typeof window.heroDefense==='function'?Math.round(window.heroDefense()):6;
    const threat=e.lvl-(p.level||1),threatLabel=threat>=6?'Смертельная':threat>=3?'Высокая':threat>=1?'Средняя':'Обычная';
    const foeTag=e.elite?'👑 ЭЛИТНЫЙ ВРАГ':a.stage===10?'👑 ФИНАЛЬНЫЙ БОСС':'ВРАГ';
    body=`<div class="v20-battle v38-battle ${e.elite?'v32-elite':''}"><section class="v38-enemy-card"><div class="v38-enemy-top"><div class="v38-foe">${e.icon}</div><div class="v38-enemy-title"><small>${foeTag} • УРОВЕНЬ ${e.lvl}</small><h2>${esc2(e.name)}</h2></div></div><div class="v20-hpbar"><i style="width:${pct}%"></i></div><div class="v38-enemy-hp">❤️ ${e.hp}/${e.max}</div><div class="v38-enemy-stats"><span>⚔️ <b>${e.atk}</b><small>Атака</small></span><span>🛡️ <b>${e.armor}</b><small>Защита</small></span><span>⚠️ <b>${threatLabel}</b><small>Угроза</small></span></div></section><div class="v38-player-card"><div><b>${esc2(p.name||'Безымянный')}</b><small>Уровень ${p.level||1}</small></div><strong>❤️ ${a.hp}/${a.maxHp||hpMax()}</strong><div class="v20-hpbar hero"><i style="width:${hpPct}%"></i></div><div class="v38-player-stats"><span>⚔️ ${playerAttack} атака</span><span>🛡️ ${playerArmor} защита</span><span>🟢 ${Math.max(0,p.st||0)}/${stMax()} выносливость</span></div></div><div class="v38-actions-title">ДЕЙСТВИЯ</div><div class="v20-actions v38-actions"><button data-v20-action="combat" data-id="attack"><span class="v38-action-icon">⚔️</span><b>Атака</b><small>Надёжный удар</small></button><button data-v20-action="combat" data-id="power"><span class="v38-action-icon">💥</span><b>Сильный удар</b><small>−18 выносливости</small></button><button data-v20-action="combat" data-id="defend"><span class="v38-action-icon">🛡️</span><b>Защита</b><small>Снизить ответный урон</small></button><button data-v20-action="combat" data-id="potion"><span class="v38-action-icon">🧪</span><b>Зелье</b><small>+45 HP</small></button></div></div>`}
  const logs=(a.log||[]).map(x=>`<div>${esc2(x)}</div>`).join('');document.getElementById('main').innerHTML=`<section class="v20-page v38-raid-page"><div class="v20-run-head"><button class="v20-icon" data-v20-action="leaveRaid">←</button><div><div class="v20-kicker">${esc2(caves.find(c=>c.id===a.cave)?.name||'РЕЙД')}</div><h1>ЭТАП ${a.stage}/10</h1><p>${stageName}</p></div><div class="v20-counter">❤️<b>${a.hp}</b><small>здоровье</small></div></div>${map}${summary}${body}<details class="v38-log"><summary>📜 Журнал боя <b>${(a.log||[]).length}</b></summary><div class="v20-log">${logs}</div></details></section>`;window.scrollTo(0,0)}'''
s=s[:start]+new+s[end:]
css='''<style id="nord-v38-raid-ui">body[data-screen="raids"] .v38-raid-page{padding-bottom:92px}body[data-screen="raids"] .v34-mapline{margin:7px 0 8px}.v38-raid-details{margin:8px 0;border:1px solid #2f4c52;border-radius:14px;background:linear-gradient(160deg,#0b1a20,#071217);overflow:hidden}.v38-raid-details>summary{list-style:none;display:flex;gap:7px;align-items:center;justify-content:space-between;padding:9px 10px;color:#a9b9b6;font-size:9px;cursor:pointer;touch-action:manipulation}.v38-raid-details>summary::-webkit-details-marker{display:none}.v38-raid-details>summary span{padding:4px 7px;border:1px solid #274149;border-radius:999px;background:#09151a}.v38-raid-details>summary b{font-size:15px;color:#7ad7d0}.v38-raid-details-body{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px;padding:0 8px 8px;border-top:1px solid #21373c}.v38-raid-details-body .v34-chip{min-width:0;padding:7px 8px;border:1px solid #293f43;border-radius:10px;background:#091418;color:#91a5a1;font-size:8px;line-height:1.25}.v38-raid-details-body .v34-chip b{display:block;color:#e1cfaa;font-size:9px;margin-bottom:2px}.v38-battle{padding:10px!important;border-radius:17px!important}.v38-enemy-card{padding:10px;border:1px solid #533b43;border-radius:15px;background:radial-gradient(circle at 78% 20%,rgba(143,63,72,.16),transparent 38%),#0b1217}.v38-enemy-top{display:flex;align-items:center;gap:10px}.v38-foe{width:50px;height:50px;display:grid;place-items:center;font-size:36px;flex:none;border-radius:13px;background:#0d171d;border:1px solid #2a4147;filter:drop-shadow(0 7px 12px #000)}.v38-enemy-title small{color:#b47e88;font-size:8px;letter-spacing:1.15px}.v38-enemy-title h2{margin:3px 0 0;color:#f0dfbd;font-size:21px}.v38-enemy-hp{color:#f0b8bf;font-size:9px;margin-top:4px}.v38-enemy-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:5px;margin-top:7px}.v38-enemy-stats span{padding:6px 4px;border:1px solid #2a4045;border-radius:10px;background:#09151a;text-align:center;color:#d6dfdc;font-size:9px}.v38-enemy-stats b{font-size:12px;color:#f0dfbd;margin-left:2px}.v38-enemy-stats small{display:block;color:#778f8c;font-size:7px;margin-top:2px}.v38-player-card{margin-top:8px;padding:9px;border:1px solid #294a51;border-radius:14px;background:#08171d}.v38-player-card b{color:#ead9b5;font-size:12px}.v38-player-card small{display:block;color:#7d9390;margin-top:2px;font-size:8px}.v38-player-card strong{float:right;color:#f0b6c0;font-size:11px;margin-top:-18px}.v38-player-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:5px;margin-top:7px;color:#8fa29f;font-size:7px}.v38-player-stats span{padding:5px 4px;border:1px solid #243b40;border-radius:9px;background:#091419;text-align:center}.v38-actions-title{margin:8px 2px 5px;color:#6fd8d2;font-size:9px;letter-spacing:2px;font-weight:800}.v38-actions{position:static!important;display:grid!important;grid-template-columns:repeat(2,1fr)!important;gap:6px!important;margin:0!important;padding:0!important;background:none!important;border:0!important;box-shadow:none!important;backdrop-filter:none!important;-webkit-backdrop-filter:none!important}.v38-actions button{min-height:58px!important;padding:7px!important;border:1px solid #2e4a52!important;border-radius:13px!important;background:linear-gradient(160deg,#10242b,#081319)!important;display:grid;grid-template-columns:34px 1fr;grid-template-rows:auto auto;column-gap:6px;align-items:center;text-align:left!important}.v38-actions button:active{transform:scale(.985);border-color:#72d8d2!important}.v38-action-icon{grid-row:1/3;display:grid;place-items:center;font-size:20px}.v38-actions button b{font-size:11px!important;color:#ead8b2!important}.v38-actions button small{font-size:8px!important;color:#7e9390!important;margin-top:1px!important}.v38-log{margin-top:8px;border:1px solid #263f45;border-radius:13px;background:#081419;overflow:hidden}.v38-log>summary{list-style:none;padding:8px 10px;color:#a7b9b5;font-size:9px;cursor:pointer;touch-action:manipulation;display:flex;justify-content:space-between}.v38-log>summary::-webkit-details-marker{display:none}.v38-log>summary b{color:#6fd8d2}.v38-log .v20-log{padding:0 8px 8px;margin-top:0}@media(max-width:520px){.v38-enemy-stats,.v38-player-stats{grid-template-columns:repeat(3,1fr)}.v38-actions button{min-height:56px!important}}</style>'''
if 'id="nord-v38-raid-ui"' not in s:s=s.replace('</head>',css+'</head>',1)
# Remove the oversized heart counter and replace it with compact HP/MP bars.
compact=r'''<style id="nord-v40-raid-resources">.v38-raid-page .v20-counter{width:100%!important;max-width:none!important;height:auto!important;min-height:0!important;padding:7px 10px!important;margin:6px 0 7px!important;display:grid!important;grid-template-columns:18px 1fr auto!important;gap:6px!important;align-items:center!important;border-radius:11px!important;background:#081419!important;box-shadow:inset 0 0 0 1px #29434a}.v38-raid-page .v20-counter>b{font-size:10px!important}.v38-raid-page .v20-counter>small{font-size:7px!important}.v38-raid-page .v20-counter:after{content:'🔷 0/50';display:block;color:#8eb9df;font-size:8px;border-left:1px solid #29434a;padding-left:8px}.v38-raid-page .v20-counter{color:#ff8da0}</style>'''
if 'nord-v40-raid-resources' not in s:s=s.replace('</head>',compact+'</head>',1)
# Local WebAudio effects; no external files required.
sound=r'''<script id="nord-v40-combat-sfx">(()=>{let A=null;function tone(type){try{A=A||new(window.AudioContext||window.webkitAudioContext)();if(A.state==='suspended')A.resume();let o=A.createOscillator(),g=A.createGain(),n=A.currentTime;let f=type==='potion'?260:type==='defend'?150:type==='power'?75:210;o.type=type==='power'?'sawtooth':'triangle';o.frequency.setValueAtTime(f,n);o.frequency.exponentialRampToValueAtTime(type==='power'?42:f*1.8,n+.11);g.gain.setValueAtTime(.0001,n);g.gain.exponentialRampToValueAtTime(.07,n+.012);g.gain.exponentialRampToValueAtTime(.0001,n+.14);o.connect(g).connect(A.destination);o.start(n);o.stop(n+.15)}catch(e){}}document.addEventListener('click',e=>{let b=e.target.closest('[data-v20-action="combat"]');if(!b)return;let id=b.getAttribute('data-id');tone(id==='potion'?'potion':id==='defend'?'defend':id==='power'?'power':'attack')},{passive:true})})();</script>'''
if 'nord-v40-combat-sfx' not in s:s=s.replace('</body>',sound+'</body>',1)
p.write_text(s,encoding='utf-8')
